text:
{
 "reason": {
  "es": "内閣《ないかく》は、ふつうの国《くに》の公務員《こうむいん》（一般職《いっぱんしょく》）の給料《きゅうりょう》をかえるのにあわせて、特別職《とくべつしょく》（大臣《だいじん》など）の給料《きゅうりょう》の額《がく》もかえる必要《ひつよう》があるため、としている。",
  "hs": "内閣は、一般職《いっぱんしょく》の国家公務員の給与《きゅうよ》改定（給料を改めること）にともない、特別職の職員の給与《きゅうよ》の額も改定する必要があるため、としている。",
  "std": "内閣は、一般職の国家公務員の給与改定に伴い、特別職の職員の給与の額の改定を行う必要があるためとしている。",
  "univ": "内閣は、一般職の国家公務員の給与改定に伴い、特別職の職員の給与の額の改定を行う必要があるためとしている。"
 },
 "who": {
  "es": "内閣総理大臣《ないかくそうりだいじん》など、特別職《とくべつしょく》の国《くに》の公務員《こうむいん》。内閣総理大臣秘書官《ないかくそうりだいじんひしょかん》、常勤《じょうきん》の委員《いいん》など。2025年《ねん》日本《にほん》国際博覧会《こくさいはくらんかい》の政府代表《せいふだいひょう》と、2027年《ねん》国際《こくさい》園芸《えんげい》博覧会《はくらんかい》の政府《せいふ》委員《いいん》。国会議員《こっかいぎいん》からえらばれた内閣総理大臣《ないかくそうりだいじん》や国務大臣《こくむだいじん》、副大臣《ふくだいじん》などは、しばらくの間《あいだ》、給料《きゅうりょう》と期末手当《きまつてあて》（ボーナス）の割合《わりあい》を今《いま》のままにする。",
  "hs": "内閣総理大臣などの特別職の国家公務員、内閣総理大臣秘書官、常勤の委員等、2025年日本国際博覧会政府代表、2027年国際園芸博覧会政府委員。国会議員から任命された内閣総理大臣、国務大臣、副大臣、大臣政務官などは、当分の間、俸給月額《ほうきゅうげつがく》（月の給料）と期末手当《きまつてあて》（ボーナス）の支給割合が改定前のままとなる。",
  "std": "内閣総理大臣など特別職の国家公務員、内閣総理大臣秘書官、常勤の委員等、2025年日本国際博覧会政府代表、2027年国際園芸博覧会政府委員。国会議員から任命された内閣総理大臣、国務大臣、内閣官房副長官、常勤の内閣総理大臣補佐官、副大臣、大臣政務官、常勤の大臣補佐官は、当分の間、俸給月額と期末手当の支給割合が改定前の水準とされる。",
  "univ": "内閣総理大臣等の特別職の職員、内閣総理大臣秘書官、常勤の委員等、2025年日本国際博覧会政府代表及び2027年国際園芸博覧会政府委員。内閣総理大臣並びに国務大臣、内閣官房副長官、常勤の内閣総理大臣補佐官、副大臣、大臣政務官及び常勤の大臣補佐官のうち国会議員から任命されたものについては、当分の間、俸給月額及び期末手当の支給割合を改定前の水準とする。"
 },
 "committee": {
  "es": "衆議院《しゅうぎいん》では、内閣委員会《ないかくいいんかい》で、ほかの2つの法律案《ほうりつあん》といっしょに話《はな》し合《あ》った。平《たいら》大臣《だいじん》が説明《せつめい》し、質問《しつもん》と討論《とうろん》のあと、この法律案《ほうりつあん》は賛成《さんせい》が多《おお》く、そのまま通《とお》った。参議院《さんぎいん》でも、内閣委員会《ないかくいいんかい》で3つをいっしょに話《はな》し合《あ》った。世代《せだい》ごとの給料《きゅうりょう》の分《わ》け方《かた》、仕事《しごと》の力《ちから》や成果《せいか》にもとづく人事《じんじ》、地域手当《ちいきてあて》の見直《みなお》しなどについて、質問《しつもん》があった。れいわ新選組《しんせんぐみ》は、この法律案《ほうりつあん》に反対《はんたい》した。この法律案《ほうりつあん》は、賛成《さんせい》が多《おお》く、そのまま通《とお》った。",
  "hs": "衆議院では内閣委員会で、ほかの2つの法律案とあわせて審査《しんさ》した。平国務大臣が趣旨《しゅし》を説明し、質疑と討論のあと、この法律案は賛成多数で原案のとおり可決された。参議院でも内閣委員会で3法律案を一括《いっかつ》して審査《しんさ》し、世代間の給与《きゅうよ》配分についての人事院の認識、能力・実績にもとづく人事管理の徹底《てってい》、地域手当の見直しの在り方などについて質疑があった。討論では、れいわ新選組がこの法律案に反対した。この法律案は多数で原案どおり可決された。",
  "std": "衆議院内閣委員会では、一般職給与法改正案、国家公務員育児休業法改正案と一括して審査し、平国務大臣の趣旨説明、質疑、討論を経て、賛成多数で原案のとおり可決した。参議院内閣委員会では、3法律案を一括して議題とし、世代間の給与配分に対する人事院の認識、能力・実績に基づく人事管理の徹底、地域手当の見直しの在り方などについて質疑が行われた。討論では、れいわ新選組が本法律案に反対の意見を述べた。採決の結果、多数で原案どおり可決すべきものと決定した。",
  "univ": "衆議院内閣委員会では、3法律案が12月10日に付託され、翌11日平国務大臣から趣旨の説明を聴取し、12日に質疑を行った。質疑終局後、討論を行い、採決の結果、本法律案は賛成多数をもって原案のとおり可決すべきものと決した。参議院内閣委員会では、3法律案を一括して議題とし、世代間の給与配分に対する人事院の認識、能力・実績に基づく人事管理の徹底、地域手当の見直しの在り方等について質疑が行われた。討論では、れいわ新選組の大島委員より特別職給与法等改正案に反対の旨の意見が述べられた。採決の結果、本法律案は多数をもって原案どおり可決すべきものと決定された。"
 },
 "views": [
  {
   "side": "反対",
   "group": "れいわ新選組",
   "where": "衆議院 内閣委員会、参議院 内閣委員会",
   "text": {
    "es": "れいわ新選組《しんせんぐみ》は、反対《はんたい》した。大臣《だいじん》などの給料《きゅうりょう》を今《いま》のままにすることは、よいと考《かんが》えていると話《はな》した。でも、この法律案《ほうりつあん》には、れいわ新選組《しんせんぐみ》が反対《はんたい》している役目《やくめ》（大阪万博《おおさかばんぱく》の政府代表《せいふだいひょう》や、カジノ管理《かんり》委員会《いいんかい》の委員《いいん》など）の給料《きゅうりょう》を上《あ》げることがふくまれている、と話《はな》した。",
    "hs": "れいわ新選組は、反対した。大臣などの給与《きゅうよ》の据《す》え置き（今のままにすること）は評価すると述べた。一方で、会派が組織の設置に反対している大阪万博の政府代表やカジノ管理委員会の委員などの給与《きゅうよ》の引き上げがふくまれていることを、反対の理由として述べた。",
    "std": "れいわ新選組は、閣僚等の給与の据え置きは評価するとした一方、会派が組織の設置に反対している万博政府代表やカジノ管理委員会委員などの特別職の給与引き上げが含まれていることを理由に反対した。こうした役職の給与も切り離し、引き下げなどの措置を講じるべきだと述べた。",
    "univ": "れいわ新選組は、閣僚等の給与の据置きについては評価するとしつつ、大阪万博の政府代表やカジノ管理委員会の委員長・委員など、会派が組織の設置に反対している特別職の国家公務員の給与引上げが含まれていることを理由に反対した。閣僚等に加え、カジノ管理委員会委員や万博政府代表の給与も特別職給与法から切り離し、引下げなどの措置を講じるべきと述べた。"
   }
  }
